package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import java.nio.file.*;
import static org.junit.Assert.*;

public class SpatialRuntime040Test {
    @Test public void ownedLiveAttemptUsesActualNativePoseAndAnotherRunCannotReplaceCommittedHead()throws Exception{
        try(var f=new KnowledgeStoreTest.Fixture();var nativeWorld=new WorldNativeStore(f.root);var game=new EmbeddedGameClient(Path.of(".."),f.root)){
            var c=WorldLedgerTest.suite().getJSONArray("cases").getJSONObject(1);var world=f.ledger.create(WorldLedgerTest.source(c),"040 live ownership control");var before=f.ledger.observe(world.getString("id"));var plan=f.ledger.preview(WorldLedgerTest.args(before,c.getJSONArray("steps").getJSONObject(0)));assertTrue(plan.toString(),plan.getBoolean("passed"));String goal=java.util.UUID.randomUUID().toString(),run=java.util.UUID.randomUUID().toString();var earlyService=new SpatialRuntime040(f.root,f.ledger,nativeWorld,f.tabletop,f.store,game);var earlyFrame=earlyService.bind(new JSONObject().put("kind","world").put("worldId",world.getString("id")));f.ledger.reserve(before,goal,run,plan);assertThrows(IllegalStateException.class,()->earlyService.select(earlyFrame.getString("snapshotHash"),earlyFrame.getString("selectedId")));nativeWorld.start(run,goal,f.ledger.source(before),plan,true,true);
            for(int i=0;i<4000;i++){var s=nativeWorld.snapshot();if(s.has("sample")&&s.getJSONObject("sample").getInt("tick")>=12)break;Thread.sleep(5);}nativeWorld.pause();assertEquals("paused",WorldLedgerTest.settled(nativeWorld,run).getString("status"));var live=nativeWorld.snapshot();var owned=f.ledger.observe(world.getString("id"));var service=new SpatialRuntime040(f.root,f.ledger,nativeWorld,f.tabletop,f.store,game);var frame=service.bind(new JSONObject().put("kind","world").put("worldId",world.getString("id")));assertEquals("uncommitted-native-attempt",frame.getJSONObject("source").getString("phase"));assertTrue(frame.getJSONObject("source").getBoolean("livePendingAvailable"));assertTrue(owned.getJSONObject("pending").similar(frame.getJSONObject("source").getJSONObject("pending")));assertEquals(before.getJSONObject("frame").getLong("elapsedTicks")+live.getJSONObject("sample").getInt("tick"),frame.getJSONObject("source").getLong("tick"));
            for(Object raw:frame.getJSONArray("entities")){var e=(JSONObject)raw;for(Object actual:live.getJSONObject("current").getJSONArray("objects")){var o=(JSONObject)actual;if(o.getString("id").equals(e.getString("id"))){assertTrue(o.getJSONArray("position").similar(e.getJSONArray("position")));assertTrue(o.getJSONArray("rotation").similar(e.getJSONArray("rotation")));}}}assertTrue(owned.similar(f.ledger.observe(world.getString("id"))));assertEquals(before.getString("expectedHash"),owned.getString("expectedHash"));
            var unrelated=WorldFrames.copy(live).put("id",java.util.UUID.randomUUID().toString());var fallback=SpatialRuntime040.nativeFrame(owned,unrelated);assertEquals("committed-world-head",fallback.getJSONObject("source").getString("phase"));assertFalse(fallback.getJSONObject("source").getBoolean("livePendingAvailable"));assertTrue(fallback.getJSONObject("source").getBoolean("pendingOwned"));assertEquals(before.getJSONObject("frame").getLong("elapsedTicks"),fallback.getJSONObject("source").getLong("tick"));
        }
    }
    @Test public void sourceIdentitySelectionAndCameraConfigurationSurviveRestartWithoutMutation()throws Exception{
        try(var f=new KnowledgeStoreTest.Fixture();var nativeWorld=new WorldNativeStore(f.root);var game=new EmbeddedGameClient(Path.of(".."),f.root)){
            var before=f.ledger.observe(f.world);var service=new SpatialRuntime040(f.root,f.ledger,nativeWorld,f.tabletop,f.store,game);var frame=service.bind(new JSONObject().put("kind","world").put("worldId",f.world));assertEquals(before.getString("expectedHash"),frame.getJSONObject("source").getString("headHash"));assertEquals(before.getJSONObject("frame").getJSONArray("bodies").getJSONObject(0).getString("id"),frame.getString("selectedId"));assertEquals("m",frame.getJSONObject("source").getString("units"));
            service.config("top");service.select(frame.getString("snapshotHash"),frame.getString("selectedId"));var reopened=new SpatialRuntime040(f.root,f.ledger,nativeWorld,f.tabletop,f.store,game);assertEquals("top",reopened.state().getString("view"));assertEquals(frame.getString("selectedId"),reopened.read().getString("selectedId"));assertTrue(before.similar(f.ledger.observe(f.world)));assertThrows(IllegalArgumentException.class,()->service.select(frame.getString("snapshotHash"),"unknown"));
        }
    }
    @Test public void observedPlaneAndHumanKnowledgeRemainSeparateFromNativeCoordinates()throws Exception{
        try(var f=new KnowledgeStoreTest.Fixture();var nativeWorld=new WorldNativeStore(f.root);var game=new EmbeddedGameClient(Path.of(".."),f.root)){
            var observed=f.tabletop.read(f.run);var nativeBefore=f.ledger.observe(f.world);var human=f.bind();var service=new SpatialRuntime040(f.root,f.ledger,nativeWorld,f.tabletop,f.store,game);var frame=service.bind(new JSONObject().put("kind","world").put("worldId",f.world).put("observationRunId",f.run));var plane=frame.getJSONObject("observationPlane");assertEquals(2,plane.getInt("dimensions"));assertFalse(plane.getBoolean("heightKnown"));assertFalse(plane.getBoolean("alignedToNative"));assertEquals(2,plane.getJSONObject("estimate").getJSONArray("positionM").length());assertEquals(observed.getJSONArray("trace").getJSONObject(4).getJSONObject("frame").getString("imageSha256"),plane.getString("imageSha256"));assertEquals(human.getString("id"),frame.getJSONArray("associations").getJSONObject(0).getString("knowledgeId"));assertTrue(observed.similar(f.tabletop.read(f.run)));assertTrue(nativeBefore.similar(f.ledger.observe(f.world)));
            var report=SpatialReport040.build(frame);assertFalse(report.getJSONObject("files").getString("index.html").contains("data:image"));assertTrue(report.getJSONObject("files").getString("index.html").contains("alignedToNative"));
        }
    }
    @Test public void exportTamperAndExpiredSnapshotsCannotInventValidEvidence()throws Exception{
        try(var f=new KnowledgeStoreTest.Fixture();var nativeWorld=new WorldNativeStore(f.root);var game=new EmbeddedGameClient(Path.of(".."),f.root)){
            var service=new SpatialRuntime040(f.root,f.ledger,nativeWorld,f.tabletop,f.store,game);var frame=service.bind(new JSONObject().put("kind","world").put("worldId",f.world));var exported=SpatialRuntime040.exported(frame);assertTrue(SpatialRuntime040.verifyExport(exported).getBoolean("passed"));var changed=WorldFrames.copy(exported);changed.getJSONObject("frame").getJSONArray("entities").getJSONObject(0).getJSONArray("position").put(0,99);assertThrows(IllegalStateException.class,()->SpatialRuntime040.verifyExport(changed));assertThrows(IllegalStateException.class,()->service.cached("0".repeat(64)));service.pin(frame.getString("snapshotHash"));assertEquals(frame.getString("snapshotHash"),service.cached(frame.getString("snapshotHash")).getString("snapshotHash"));service.release(frame.getString("snapshotHash"));assertThrows(IllegalStateException.class,()->new SpatialRuntime040(f.root,f.ledger,nativeWorld,f.tabletop,f.store,game).cached(frame.getString("snapshotHash")));
        }
    }
    @Test public void staleNativeClockIsRefusedAndReadNeverOpensAGame()throws Exception{
        try(var f=new KnowledgeStoreTest.Fixture();var nativeWorld=new WorldNativeStore(f.root);var game=new EmbeddedGameClient(Path.of(".."),f.root)){
            var service=new SpatialRuntime040(f.root,f.ledger,nativeWorld,f.tabletop,f.store,game);assertThrows(IllegalStateException.class,service::read);assertThrows(IllegalStateException.class,()->service.bind(new JSONObject().put("kind","game")));assertFalse(game.status().getBoolean("running"));var frame=service.bind(new JSONObject().put("kind","world").put("worldId",f.world));var n=f.ledger.observe(f.world);f.ledger.restore(f.world,n.getInt("expectedRevision"),n.getString("expectedHash"),0,"");assertThrows(IllegalStateException.class,()->service.select(frame.getString("snapshotHash"),frame.getString("selectedId")));
        }
    }
}
